// On récupère la sortie du node "Social Media Content Factory"
const output = $('Social Media Content Factory').item.json.output;
const posts = output.platform_posts;

const items = [];

// Pour chaque plateforme, on crée un item avec un prompt
for (const [platform, data] of Object.entries(posts)) {
  if (!data.image_suggestion) continue;

  items.push({
    json: {
      platform,               // LinkedIn, Instagram, X, ...
      prompt: data.image_suggestion
    }
  });
}

return items;
